/**
 * Store a new draft journal.
 */

public function store(StoreJournalRequest $request)
{
    $validated = $request->validated();

    $orgId = $request->user()->organization_id;

    try {
        if (! empty($validated['post_immediately'])) {
            $journal = $this->postingService->createAndPost($orgId, $validated);
        } else {
            $journal = $this->postingService->createDraftJournal($orgId, $validated);
        }
    } catch (\InvalidArgumentException $e) {
        return redirect()->back()
            ->withInput()
            ->withErrors(['posting' => $e->getMessage()]);
    }

    return redirect()->route('finance.journals.show', $journal)
        ->with('success', $journal->status === 'posted'
            ? "Journal {$journal->journal_number} created and posted."
            : "Journal {$journal->journal_number} saved as draft."
        );
}

/**
 * Show a single journal with its lines and relations.
 */

public function authorize(): bool
{
    return $this->user()->can('create', FinJournal::class);
}

public function show(Request $request, FinJournal $journal)
{
    $this->authorize('view', $journal);

    $journal->load([
        'lines.account:id,code,name',
        'lines.costCentre:id,code,name',
        'lines.fundingStream:id,code,name',
        'lines.taxRate:id,code,name,rate',
        'fiscalPeriod:id,name,start_date,end_date',
        'postedBy:id,name',
        'createdBy:id,name',
        'reversedByJournal:id,journal_number',
    ]);

    return Inertia::render('finance/journals/Show', [
        'journal' => $journal,
    ]);
}

/**
 * Post a draft journal.
 */

public function post(Request $request, FinJournal $journal)
{
    $this->authorize('post', $journal);

    try {
        $this->postingService->post($journal);
    } catch (\InvalidArgumentException $e) {
        return redirect()->back()->withErrors(['posting' => $e->getMessage()]);
    }

    return redirect()->route('finance.journals.show', $journal)
        ->with('success', "Journal {$journal->journal_number} has been posted.");
}

/**
 * Reverse a posted journal.
 */

    public function reverse(Request $request, FinJournal $journal)
    {
        $this->authorize('reverse', $journal);

        $request->validate([
            'reason' => ['nullable', 'string', 'max:1000'],
        ]);

        try {
            if ($journal->source_type === FinFixedAssetDepreciation::class && $journal->source_id !== null) {
                $depreciation = FinFixedAssetDepreciation::query()->findOrFail($journal->source_id);
                if ((int) $depreciation->journal_id !== (int) $journal->id) {
                    throw new \InvalidArgumentException('The depreciation journal has conflicting execution lineage.');
                }
                $reversingJournal = $this->fixedAssetService->reverseDepreciation(
                    $depreciation,
                    $request->input('reason'),
                );
            } else {
                $reversingJournal = $this->postingService->reverse($journal, $request->input('reason'));
            }
        } catch (\InvalidArgumentException $e) {
            return redirect()->back()->withErrors(['posting' => $e->getMessage()]);
        }

        return redirect()->route('finance.journals.show', $reversingJournal)
            ->with('success', "Reversing journal {$reversingJournal->journal_number} created and posted.");
    }
}

public function store(Request $request)
{
    $validated = $request->validate([
        'name' => 'required|string|max:255',
        'start_date' => 'required|date',
        'end_date' => 'required|date|after:start_date',
    ]);

    FinFiscalPeriod::create([
        'organization_id' => $request->user()->organization_id,
        'name' => $validated['name'],
        'start_date' => $validated['start_date'],
        'end_date' => $validated['end_date'],
        'status' => 'open',
        'created_by' => $request->user()->id,
    ]);

    return redirect()->route('finance.fiscal-periods.index')
        ->with('success', 'Fiscal period created successfully.');
}

public function update(Request $request, FinFiscalPeriod $period)
{
    if ($period->status !== 'open') {
        return back()->withErrors(['period' => 'Only open periods can be edited.']);
    }

    $validated = $request->validate([
        'name' => 'required|string|max:255',
        'start_date' => 'required|date',
        'end_date' => 'required|date|after:start_date',
    ]);

    $period->update($validated);

    return redirect()->route('finance.fiscal-periods.index')
        ->with('success', 'Fiscal period updated successfully.');
}

    public function close(Request $request, FinFiscalPeriod $period)
    {
        if ($period->status !== 'open') {
            return back()->withErrors(['period' => 'This period is already closed.']);
        }

        // Check for unposted draft journals in this period
        $draftCount = FinJournal::forOrganization($request->user()->organization_id)
            ->where('fiscal_period_id', $period->id)
            ->where('status', 'draft')
            ->count();

        if ($draftCount > 0) {
            return back()->withErrors([
                'period' => "Cannot close period: {$draftCount} draft journal(s) still unposted.",
            ]);
        }

        $period->update([
            'status' => 'closed',
            'closed_at' => now(),
            'closed_by' => $request->user()->id,
        ]);

        return redirect()->route('finance.fiscal-periods.index')
            ->with('success', 'Fiscal period closed successfully.');
    }
}

public function store(Request $request)
{
    $validated = $request->validate([
        'code' => 'required|string|max:20',
        'name' => 'required|string|max:255',
        'type' => 'nullable|string|max:50',
        'site_id' => 'nullable|integer',
        'parent_id' => 'nullable|exists:fin_cost_centres,id',
        'is_active' => 'boolean',
    ]);

    $orgId = $request->user()->organization_id;

    // Check code uniqueness per org
    $exists = FinCostCentre::forOrganization($orgId)
        ->where('code', $validated['code'])
        ->exists();

    if ($exists) {
        return back()->withErrors(['code' => 'A cost centre with this code already exists.']);
    }

    FinCostCentre::create(array_merge($validated, [
        'organization_id' => $orgId,
        'created_by' => $request->user()->id,
    ]));

    return redirect()->route('finance.cost-centres.index')
        ->with('success', 'Cost centre created successfully.');
}

public function update(Request $request, FinCostCentre $costCentre)
{
    $validated = $request->validate([
        'code' => 'required|string|max:20',
        'name' => 'required|string|max:255',
        'type' => 'nullable|string|max:50',
        'site_id' => 'nullable|integer',
        'parent_id' => 'nullable|exists:fin_cost_centres,id',
        'is_active' => 'boolean',
    ]);

    // Check code uniqueness per org (excluding self)
    $exists = FinCostCentre::forOrganization($costCentre->organization_id)
        ->where('code', $validated['code'])
        ->where('id', '!=', $costCentre->id)
        ->exists();

    if ($exists) {
        return back()->withErrors(['code' => 'A cost centre with this code already exists.']);
    }

    $costCentre->update($validated);

    return redirect()->route('finance.cost-centres.index')
        ->with('success', 'Cost centre updated successfully.');
}

    public function destroy(Request $request, FinCostCentre $costCentre)
    {
        $costCentre->delete();

        return redirect()->route('finance.cost-centres.index')
            ->with('success', 'Cost centre deleted successfully.');
    }
}

